const { formatAmount } = require('../.build/money');
for (const [cents, expected] of [
  [0, '0.00'], [-0, '0.00'], [1, '0.01'], [99, '0.99'],
  [100, '1.00'], [123, '1.23'], [-1, '-0.01'],
  [-99, '-0.99'], [-100, '-1.00'], [-123, '-1.23'],
]) {
  assert.equal(formatAmount(cents), expected);
  assert.equal(renderInvoice('inv', cents), 'inv: $' + expected);
  assert.equal(renderReport([{ id: 'row', cents }]), 'row,' + expected);
}
assert.equal(renderReport([]), '');
assert.equal(renderReport([
  { id: 'z', cents: 100 }, { id: 'a', cents: -123 }, { id: 'm', cents: 0 },
]), 'z,1.00\na,-1.23\nm,0.00');
